arguments.content:
{
  "version": "V5",
  "phase": "grading",
  "segments": [
    {
      "id": "段1",
      "content": "WLOG通过对a施加排列把a₁<...<aₙ排序",
      "features": ["WLOG归约", "对称性利用"]
    },
    {
      "id": "段2",
      "content": "定义关键量x=a₁+...+a_{n-1}（除最大元外所有元素之和）",
      "features": ["定义关键量"]
    },
    {
      "id": "段3",
      "content": "声明对n做强归纳作为整体证明策略",
      "features": ["归纳策略声明"]
    },
    {
      "id": "段4",
      "content": "根据M中元素相对x的位置（x是否∈M、是否有y>x）划分三种情况",
      "features": ["案例划分", "分类标准确立"]
    },
    {
      "id": "段5",
      "content": "Case 1条件：x∈M且∃y∈M with y>x；由条件推出n≥3",
      "features": ["案例条件识别", "派生约束"]
    },
    {
      "id": "段6",
      "content": "在n-1个小元素中定义'坏指标'i：x-aᵢ∈M或s-aᵢ∈M",
      "features": ["定义坏指标", "反面量构造"]
    },
    {
      "id": "段7",
      "content": "论证坏指标到M\\{x}的映射是单射：x-aᵢ因x∈M且aᵢ>0映到M\\{x}，s-aᵢ>x映到M∩(x,∞)",
      "features": ["注入性论证", "映射构造"]
    },
    {
      "id": "段8",
      "content": "由|M\\{x}|=n-2和单射推出至多n-2个坏指标，故n-1个中至少存在一个好指标r",
      "features": ["鸽巢论证", "存在性论证"]
    },
    {
      "id": "段9",
      "content": "构造归约参数：t=x-aᵣ，M'=M∩(-∞,t]；由x和y都被排除推出|M'|≤n-3",
      "features": ["归约参数构造", "规模估计"]
    },
    {
      "id": "段10",
      "content": "对n-2个剩余元素（去掉aᵣ和aₙ）与M'应用归纳假设，得到排列p'",
      "features": ["应用归纳假设"]
    },
    {
      "id": "段11",
      "content": "构造完整排列：p'在前，然后aᵣ，然后aₙ（交换使aₙ在倒数第二位）",
      "features": ["排列构造", "交换技巧"]
    },
    {
      "id": "段12",
      "content": "验证构造：aᵣ前的前缀和≤t避开M'，到aᵣ的和避开M（由r的选择），最终和s∉M",
      "features": ["验证", "前缀和分析"]
    },
    {
      "id": "段13",
      "content": "Case 2条件：x∉M且∃y∈M with y>x；推出|M∩(-∞,x]|≤n-2",
      "features": ["案例条件识别", "规模估计"]
    },
    {
      "id": "段14",
      "content": "构造归约参数M'=M∩(-∞,x]，对a₁,...,a_{n-1}用归纳（其和x∉M'满足归纳条件）",
      "features": ["归约参数构造", "应用归纳假设"]
    },
    {
      "id": "段15",
      "content": "边界处理与构造：M'空用恒等排列，否则得p'后将aₙ放最后",
      "features": ["边界处理", "排列构造"]
    },
    {
      "id": "段16",
      "content": "验证构造：前n-1跳前缀和≤x避开M'，最终和s∉M",
      "features": ["验证", "前缀和分析"]
    },
    {
      "id": "段17",
      "content": "Case 3条件：所有m∈M满足m≤x；令z=max(M)，M'=M\\{z}",
      "features": ["案例条件识别", "归约参数构造"]
    },
    {
      "id": "段18",
      "content": "对a₁,...,a_{n-1}与M'（|M'|=n-2）应用归纳假设得排列p'",
      "features": ["应用归纳假设"]
    },
    {
      "id": "段19",
      "content": "交换构造：若p'某前缀和在位置k等于z，把aₙ放位置k（因aₙ>a_{p'(k)}跳过z），a_{p'(k)}放最后",
      "features": ["交换技巧", "排列构造", "条件分支处理"]
    },
    {
      "id": "段20",
      "content": "平凡情况：若无前缀和等于z，则p'已避开M'∪{z}=M，无需调整",
      "features": ["平凡情况处理", "验证"]
    },
    {
      "id": "段21",
      "content": "WLOG还原：一般（未排序）情形通过复合排序置换归约到已排序情形",
      "features": ["WLOG归约", "还原闭合"]
    }
  ]
}
